const t=document.getElementById('menuToggle'),n=document.getElementById('mainNav');if(t&&n){t.onclick=()=>{const o=t.getAttribute('aria-expanded')!=='true';t.setAttribute('aria-expanded',String(o));t.textContent=o?'×':'☰';n.classList.toggle('open',o);};n.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{t.setAttribute('aria-expanded','false');t.textContent='☰';n.classList.remove('open');}));}
